    pub fn error_if_any_error(results: Vec<Self>) -> Self {
        if results.iter().any(|s| match s {
            ExitCode::GeneralError => true,
            _ => false,
        }) {
            return ExitCode::GeneralError;
        }
        ExitCode::Success
    }
}

