    1,  1,  3, 10,  1,  1,  1,  1,  4,  4,  8,  4, 10,
];

pub fn score(string: &str) -> usize {
    string
        .chars()
        .map(|c| match c {
            _ if c.is_ascii_uppercase() => SCORETABLE[c as usize - 'A' as usize],
            _ if c.is_ascii_lowercase() => SCORETABLE[c as usize - 'a' as usize],
            _ => 0,
        })
        .sum()
}

