        .map(|p| Path::new(&p).join(".metabrowser.yaml"))
        .and_then(|p| Config::from_file(&p));

    match result {
        Ok(c) => println!("{:?}", c),
        Err(e) => {
            writeln!(&mut stderr(),
                     "Could not open metabrowser configuration file: {}",
                     e)
                .unwrap();
        }
    }
}

