///
/// ```
/// let mut data: Vec<i32> = vec![4, 2, 3, 1, 5];
/// sorting::efficientsorts::quick::sort(&mut data);
/// assert_eq!(vec![1, 2, 3, 4, 5], data);
/// ```
///
pub fn sort<T: PartialOrd>(array: &mut Vec<T>) {
    let n = array.len();

    if n <= 1 {
        return;
    } else if n == 2 {
        if array.first() <= array.last() {
            return;
        } else {
            array.swap(0, 1);
            return;
        }
    } else {
        unimplemented!();
    }
}

