fn clear_screen(background: Color) {
    let mut i = 0u16;
    let max = 80 * 25;

    while i < max {
        unsafe {
            *((0xb8000 + i * 2) as *mut u16) = (background as u16) << 12;
        }
        i = i + 1;
    }
}

#[no_mangle]
#[no_split_stack]
pub fn main() {
    clear_screen(LightRed);
