            match c {
                '[' | '{' | '(' => r.push(c),
                ')' => if let Some(l) = r.pop() {
                    if l != '(' {
                        return false;
                    }
                } else {
                    return false;
                },
                ']' | '}' => if let Some(l) = r.pop() {
                    if c as i32 - l as i32 != 2 {
                        return false;
                    }
                } else {
                    return false;
                },
                _ => return false,
            }
        }

        r.is_empty()
    }
}

