/// Wait the given number of SysTick ticks
pub fn wait(ticks: u32) {
  let mut n = ticks;
  let mut t = systick::get_current();
  loop {
    if systick::get_current() > t {
      t = systick::get_current();
      n -= 1;
      if n == 0 {
        break;
      }
    }
  }
}

